export const Schema = z.object({
    好感度: z.coerce.number().transform(v => Math.max(0, v)),
    婚姻状态: z.enum(['未婚', '已婚']),
    团子状态: z.enum(['未收养', '已收养']),
    若有希: z.object({
        穿搭: z.object({
            上搭: z.string(),
            下搭: z.string(),
        }),
        情绪: z.string(),
    }),
    场景: z.object({
        时间: z.string(),
        地点: z.string(),
    }),
});
